          v_created boolean := false;

          v_mode text;


          v_invoice record;
          v_header jsonb;

          v_timesheet_ids uuid[];
          v_snap_ids uuid[];

            v_sum_ex numeric := 0;
      v_sum_vat numeric := 0;
