      -- run-level totals audit
      v_prev_ex numeric := 0;
      v_prev_vat numeric := 0;
      v_prev_inc numeric := 0;
      v_prev_status text := null;
      v_prev_invoice_no text := null;

      v_new_ex numeric := 0;
      v_new_vat numeric := 0;
