      v_reimb_pay := round(v_exp_pay + v_mil_pay, 2);         -- reimbursements (never ERNI)

      v_wage_pay_cost := v_wage_pay;
      if v_erni_applies then
        v_wage_pay_cost := round(v_wage_pay * v_erni_mult, 2);
